// === Tab: mySketch ===
let pg;
let theShader;
let t = 64;

function preload(){
	theShader = createShader(vert, frag);
}

function setup() {
    createCanvas(600, 600, WEBGL);
	background(0);

    pg = createGraphics(600, 600);
}

function draw() {
	pg.translate(pg.width/2, pg.height/2);
	pg.rotate(PI/120);
	pg.translate(-pg.width/2, -pg.height/2);
	pg.background("#191919");
	pg.noStroke();
	pg.fill("#D05353");
	pg.circle(400, 300, 150);
	pg.fill("#E58F65");
	pg.circle(300, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 200);
	pg.strokeWeight(10);
	pg.stroke("#F9E784");
	pg.line(50, pg.height/2, pg.width-50, pg.height/2);


	shader(theShader);
	theShader.setUniform("u_resolution", [pg.width, pg.height]);
	theShader.setUniform("u_time", millis()/1000);
	theShader.setUniform("tex0", pg);
	theShader.setUniform("px", t);

	quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

function keyPressed(){
	if (keyCode === LEFT_ARROW) {
		t += 4;
	} else if (keyCode === RIGHT_ARROW) {
		t -= 4;
	}
	t = constrain(t, 4, 256);
}


const vert = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;

void main() {
	vec4 positionVec4 = vec4(aPosition, 1.0);
	positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

	gl_Position = positionVec4;
}
`;

const frag = `
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform sampler2D tex0;
uniform float px;

void main(){
	vec2 uv = gl_FragCoord.xy/u_resolution;
	uv*=0.5;
	uv.y = 1.0-uv.y;

	float dv = px;

	vec2 i_uv = floor(uv*dv)/dv;
	vec2 f_uv = fract(uv*dv);

	//vec2( i_uv.x+1.0/dv ,i_uv.y) the pixel at the right
	vec4 tex = texture2D(tex0,i_uv+vec2(0.5/dv));

	float br = (tex.r+tex.g+tex.b)/3.0;

	float on = step(distance(f_uv,vec2(0.5)),br*0.65);

	vec3 col = vec3(tex.rgb*on);

	gl_FragColor = vec4(col*on, 1.0);
}`

